const a=e=>{var t;return e.sol.ok?((t=e.sol.reactions.A)==null?void 0:t[2])??0:0},n=e=>(Number(e.params.g)+Number(e.params.q))*Number(e.params.a)**2/2,s=e=>{var t;return e.sol.ok?((t=e.sol.memberMap.BK)==null?void 0:t.stations[0].M)??0:0},i=[{id:"l.rc-sys-cantilever.single",xp:20,title:{en:"Remove the back arm: a single cantilever frame — read M = wa²/2 in the hand method",ar:"شيل الذراع الخلفي: إطار كابولي واحد — اقرا M = wa²/2 في الحل اليدوي"},check:e=>e.template==="tframe"&&Number(e.params.a2)===0&&e.tab==="hand"},{id:"l.rc-sys-cantilever.both",xp:30,title:{en:"Equal arms, live load on both: the column moment vanishes and the normal force peaks",ar:"ذراعين متساويين والحمل الحي على الاتنين: عزم العمود بيختفي والقوة العمودية في أقصاها"},check:e=>e.template==="tframe"&&e.params.load==="both"&&Number(e.params.a2)===Number(e.params.a)&&Number(e.params.q)>0&&Math.abs(a(e))<1},{id:"l.rc-sys-cantilever.worst",xp:30,title:{en:"Find the load case that bends the column of a T-frame most",ar:"لاقي حالة التحميل اللي بتحني عمود الإطار T أكتر حاجة"},check:e=>e.template==="tframe"&&Number(e.params.a2)>0&&e.params.load!=="both"&&Number(e.params.q)>0&&e.tab==="hand"}],m=[{id:"l.rc-sys-cantilever.balance",xp:50,title:{en:"Balance the grandstand roof: without live load, bring the base moment below 5% of the front arm's moment with the counterweight",ar:"وازن سقف المدرج: من غير حمل حي، نزّل عزم القاعدة تحت 5% من عزم الذراع الأمامي بثقل الموازنة"},check:e=>e.template==="tframe"&&Number(e.params.q)===0&&Number(e.params.W)>0&&Number(e.params.a2)>0&&Math.abs(a(e))<.05*(Number(e.params.g)*Number(e.params.a)**2/2)}],o=[{id:"l.rc-sys-cantilever.strut",xp:40,title:{en:"Prop the cantilever with a strut until its root moment is below 20% of wa²/2",ar:"اسند الكابولي بدعامة ضغط لحد ما عزم جذره يبقى أقل من 20% من wa²/2"},check:e=>e.template==="linkframe"&&e.params.link==="strut"&&Math.abs(s(e))<.2*n(e)},{id:"l.rc-sys-cantilever.stretch",xp:40,title:{en:"Hang it from a tie that stretches, then give the tie more steel and watch its force come back",ar:"علّقه في شداد بيستطيل، وبعدين ادّي الشداد حديد أكتر وشوف قوته بترجع"},check:e=>e.template==="linkframe"&&e.params.link==="tie"&&e.params.tie==="rc"&&Number(e.params.kt)>=3&&e.tab==="hand"},{id:"l.rc-sys-cantilever.base",xp:30,title:{en:"With any link, check the base moment in the results: still wa²/2",ar:"بأي وصلة، راجع عزم القاعدة في النتائج: لسه wa²/2"},check:e=>e.template==="linkframe"&&e.params.link!=="none"&&e.tab==="results"&&Math.abs(Math.abs(a(e))-n(e))<1}],r=[{id:"l.rc-sys-cantilever.bars",xp:20,title:{en:"Show the bars and follow the cantilever's top steel down the outer face of the column",ar:"اعرض الحديد وتابع حديد الكابولي العلوي وهو نازل على الوش الخارجي للعمود"},check:e=>e.mode==="studio"&&e.overlay==="bars"},{id:"l.rc-sys-cantilever.root",xp:30,title:{en:"Click the cantilever root and read its design",ar:"اضغط على جذر الكابولي واقرا تصميمه"},check:e=>e.mode==="studio"&&e.selected==="cant"}],$={sections:[{id:"uses",title:{en:"Cantilever frames and where they are used",ar:"الإطارات الكابولي وبتستخدم فين"},blocks:[{t:"p",text:{en:"A **cantilever frame** is a column fixed into its footing with a beam cantilevering from its top: nothing supports the far end, so everything the beam carries comes back to the column and the footing as a moment. It covers spaces that must stay free on one side — the roof over the seats of a **grandstand**, the **canopy** of a petrol station or a bus stop, a loading **platform**. Its family:",ar:"الـ**إطار الكابولي** عمود متثبت في قاعدته وكمرة طالعة منه كابولي من فوق: مفيش حاجة شايلة الطرف البعيد، فكل اللي الكمرة شايلاه بيرجع للعمود والقاعدة كعزم. بيغطي أماكن لازم تفضل فاضية من ناحية — سقف كراسي **المدرج**، و**مظلة** البنزينة أو موقف الأتوبيس، و**رصيف** التحميل. وعيلته:"}},{t:"table",head:[{en:"Frame",ar:"الإطار"},{en:"Shape",ar:"الشكل"}],rows:[[{en:"single cantilever frame",ar:"إطار كابولي"},{en:"Γ: a column and one arm",ar:"Γ: عمود وذراع واحد"}],[{en:"double cantilever frame",ar:"إطار كابولي مزدوج"},{en:"T or Y: arms on both sides balance each other",ar:"T أو Y: ذراعين على الجنبين بيوازنوا بعض"}],[{en:"with a compression link",ar:"بوصلة ضغط"},{en:"a strut from the column to the arm, below it",ar:"دعامة من العمود للذراع، تحته"}],[{en:"with a tension link",ar:"بوصلة شد"},{en:"a tie from a mast above the column to the arm",ar:"شداد من صاري فوق العمود للذراع"}]]},{t:"quiz",q:{kind:"mcq",q:{en:"The load on a cantilever frame's arm reaches the footing as…",ar:"الحمل على ذراع الإطار الكابولي بيوصل للقاعدة كـ…"},options:[{en:"a normal force and a large moment",ar:"قوة عمودية وعزم كبير"},{en:"a normal force only",ar:"قوة عمودية بس"},{en:"a horizontal thrust",ar:"دفع أفقي"}],answer:0,explain:{en:"Nothing supports the tip, so the whole moment wa²/2 goes down the column into the footing.",ar:"مفيش حاجة شايلة الطرف، فالعزم كله wa²/2 بينزل في العمود للقاعدة."}}}]},{id:"spans",title:{en:"How far can it reach?",ar:"يوصل لحد فين؟"},blocks:[{t:"table",head:[{en:"Cantilever L",ar:"الكابولي L"},{en:"System",ar:"النظام"}],rows:[["≤ 2 m",{en:"a cantilever slab is enough",ar:"بلاطة كابولي كفاية"}],["2–6 m",{en:"cantilever frame",ar:"إطار كابولي"}],["6–7.5 m",{en:"a 6 m cantilever frame plus a 1.5 m cantilever slab beyond it",ar:"إطار كابولي 6 م زائد بلاطة كابولي 1.5 م بعده"}],["> 7.5 m",{en:"add a link: a tie from above or a strut (post) below — link frames cover 6–10 m",ar:"ضيف وصلة: شداد من فوق أو دعامة (عمود) من تحت — الإطارات بوصلة بتغطي 6–10 م"}]],caption:{en:"A horizontal arm reaches 6 m, an inclined one (a stand roof rising outwards) 8 m. Beyond 2.0 m an overhang is a cantilever frame, not a slab; up to 2.0 m the cantilever slab is about L_c/10 thick at its root.",ar:"الذراع الأفقي بيوصل لـ 6 م، والمائل (سقف مدرج طالع لبره) لـ 8 م. وبعد 2.0 م الكابولي بيبقى إطار كابولي، مش بلاطة؛ ولحد 2.0 م بلاطة الكابولي تخانتها حوالي L_c/10 عند الجذر."}},{t:"quiz",q:{kind:"mcq",q:{en:"A canopy must reach 9 m beyond its columns. The system?",ar:"مظلة لازم توصل 9 م بعد أعمدتها. النظام؟"},options:[{en:"a cantilever frame with a tie or a strut",ar:"إطار كابولي بشداد أو دعامة"},{en:"a plain cantilever frame",ar:"إطار كابولي عادي"},{en:"a cantilever slab",ar:"بلاطة كابولي"}],answer:0,explain:{en:"Beyond 7.5 m a link is needed; link frames reach 6–10 m.",ar:"بعد 7.5 م لازم وصلة؛ والإطارات بوصلة بتوصل 6–10 م."}}}]},{id:"dims",title:{en:"Concrete dimensions",ar:"الأبعاد الخرسانية"},blocks:[{t:"eq",tex:["t = \\dfrac{L_c}{5},\\qquad t_{col} = (0.8 \\to 1.0)\\,t,\\qquad b = \\max\\left(0.30,\\ \\dfrac{S}{20}\\right)","t = \\dfrac{L}{7} \\to \\dfrac{L}{8}","t_{end} = \\max\\left(\\dfrac{t}{2},\\ \\dfrac{S}{12},\\ t - \\dfrac{L_c}{3}\\right)"],caption:{en:"Root depth without and with a link; the arm tapers to t_end at its tip; the link member is b × b.",ar:"عمق الجذر من غير وصلة وبوصلة؛ والذراع بيتدرّج لحد t_end عند طرفه؛ والوصلة b × b."}},{t:"p",text:{en:"**Example:** a 4.5 m canopy on frames 5.5 m apart: $t = 4.5/5 = 0.90$ m at the root, $b = \\max(0.30,\\ 0.275) = 0.30$ m, the tip $\\max(0.45,\\ 0.458,\\ 0.9 - 1.5) = 0.46$ m; the column 0.72–0.90 m deep. With a link the root would need only about $L/7.5$.",ar:"**مثال:** مظلة 4.5 م على إطارات كل 5.5 م: $t = 4.5/5 = 0.90$ م عند الجذر، و $b = \\max(0.30,\\ 0.275) = 0.30$ م، والطرف $\\max(0.45,\\ 0.458,\\ 0.9 - 1.5) = 0.46$ م؛ والعمود عمقه 0.72–0.90 م. وبوصلة الجذر كان هيحتاج حوالي $L/7.5$ بس."}},{t:"p",text:{en:"**A cantilever frame that carries another system at its tip** — a saw-tooth girder, a bridge, the end of a roof — works under a heavy point load at the end of its arm rather than a spread load, and is made much deeper: $t = L_c/(2.0 \\to 3.0)$ at the root and for the column. **Example:** a 4.5 m arm carrying a girder at its tip: $4.5/2 = 2.25$ to $4.5/3 = 1.50$ m — take 1.80 m ($L_c/2.5$) for the root and the column.",ar:"**الإطار الكابولي اللي شايل نظام تاني عند طرفه** — كمرة منشارية، أو كوبري، أو طرف سقف — بيشتغل تحت حمل مركز تقيل في آخر ذراعه بدل الحمل الموزع، وبيتعمل أعمق بكتير: $t = L_c/(2.0 \\to 3.0)$ عند الجذر وللعمود. **مثال:** ذراع 4.5 م شايل كمرة عند طرفه: من $4.5/2 = 2.25$ لـ $4.5/3 = 1.50$ م — خد 1.80 م ($L_c/2.5$) للجذر والعمود."}},{t:"quiz",q:{kind:"num",q:{en:"A 3.5 m cantilever frame. Root depth by the rule (m)?",ar:"إطار كابولي 3.5 م. عمق الجذر بالقاعدة (م)؟"},answer:.7,tol:.003,unit:"m",explain:{en:"$L_c/5 = 0.70$ m.",ar:"$L_c/5 = 0.70$ م."}}}]},{id:"statics",title:{en:"Statics of a single and a double cantilever frame",ar:"اتزان الإطار الكابولي والمزدوج"},blocks:[{t:"p",text:{en:"A single cantilever frame is statically determinate: the root moment $wa^2/2$ runs unchanged down the column to the footing, with $N = wa$. **Example:** a 4 m arm with $w = 30 + 15 = 45$ kN/m: $M = 45\\times4^2/2 = 360$ kN·m at the root and at the base, $N = 180$ kN. A T-frame balances one arm with the other, so its column carries only the **difference**:",ar:"الإطار الكابولي الواحد محدد استاتيكياً: عزم الجذر $wa^2/2$ بينزل زي ما هو في العمود لحد القاعدة، و $N = wa$. **مثال:** ذراع 4 م عليه $w = 30 + 15 = 45$ kN/m: $M = 45\\times4^2/2 = 360$ kN·m عند الجذر وعند القاعدة، و $N = 180$ kN. والإطار T بيوازن ذراع بالتاني، فعموده بيشيل **الفرق** بس:"}},{t:"eq",tex:["M_{col} = \\dfrac{w_f\\,a^2}{2} - \\dfrac{w_b\\,a_2^2}{2},\\qquad N = w_f\\,a + w_b\\,a_2"]},{t:"p",text:{en:"The live load can be on one arm only. With dead load $g$ on both arms and the total $g + q$ on one of them, the column moment is largest; with $g + q$ on both, the normal force is largest (and, for equal arms, the moment vanishes). **Example:** a T-frame with two 5 m arms, $g = 30$, $q = 15$ kN/m: live on both → $M = 0$, $N = 450$ kN; live on one arm → $M = (45 - 30)\\times5^2/2 = 187.5$ kN·m with $N = 375$ kN.",ar:"الحمل الحي ممكن يبقى على ذراع واحد بس. بحمل ميت $g$ على الذراعين والكلي $g + q$ على واحد منهم، عزم العمود بيبقى أكبر حاجة؛ وبـ $g + q$ على الاتنين القوة العمودية بتبقى أكبر حاجة (ولو الذراعين متساويين، العزم بيختفي). **مثال:** إطار T بذراعين 5 م، و $g = 30$ و $q = 15$ kN/m: الحي على الاتنين ← $M = 0$ و $N = 450$ kN؛ والحي على ذراع واحد ← $M = (45 - 30)\\times5^2/2 = 187.5$ kN·m مع $N = 375$ kN."}},{t:"lab",lab:"frame",height:470,props:{template:"tframe",lockTemplate:!0,missions:i},caption:{en:"A T-frame with tapered arms: change the arms, the loads and where the live load sits; the Hand method tab lists all three load cases.",ar:"إطار T بأذرع متدرّجة: غيّر الأذرع والأحمال ومكان الحمل الحي؛ وتبويب الحل اليدوي بيعرض حالات التحميل التلاتة."}},{t:"quiz",q:{kind:"num",q:{en:"T-frame, arms 4 m each, g = 25, q = 10 kN/m. Column moment with the live load on one arm only (kN·m)?",ar:"إطار T، كل ذراع 4 م، و g = 25 و q = 10 kN/m. عزم العمود والحمل الحي على ذراع واحد بس (kN·m)؟"},answer:80,tol:.003,unit:"kN·m",explain:{en:"$(35 - 25)\\times4^2/2 = 80$ kN·m.",ar:"$(35 - 25)\\times4^2/2 = 80$ kN·m."}}}]},{id:"footing",title:{en:"The footing: shift it and keep it from overturning",ar:"القاعدة: رحّلها وامنعها من الانقلاب"},blocks:[{t:"p",text:{en:"The permanent moment of a cantilever frame would tilt its footing and load the soil on one edge. So the footing is **shifted** towards the loaded side by $e = M/Y$, usually 0.5–1.0 m, until the resultant of the dead load passes through its centre and the soil pressure is uniform; the rest of the moment (live load, wind) is taken by a footing large enough to be safe against **overturning**. A T-frame whose load can reverse is not shifted for the reversing part — it is sized for both signs.",ar:"العزم الدائم للإطار الكابولي هيميّل قاعدته ويحمّل التربة على حرف واحد. علشان كده القاعدة بـ**تترحّل** ناحية الجنب المحمّل بمسافة $e = M/Y$، وغالباً 0.5–1.0 م، لحد ما محصلة الحمل الميت تعدّي في نصها وضغط التربة يبقى منتظم؛ وباقي العزم (الحمل الحي والرياح) بتشيله قاعدة كبيرة كفاية تبقى في الأمان ضد **الانقلاب**. والإطار T اللي حمله ممكن يعكس مابيترحّلش للجزء اللي بيعكس — بيتكبّر على الإشارتين."}},{t:"eq",tex:"e = \\dfrac{M}{Y}",caption:{en:"Y = the vertical reaction (the normal force of the column at the footing).",ar:"Y = رد الفعل الرأسي (القوة العمودية للعمود عند القاعدة)."}},{t:"p",text:{en:"**Example:** a T-frame with a 4.5 m front arm and a 3 m back arm under a dead load of 30 kN/m: $M_D = 30\\times(4.5^2 - 3^2)/2 = 168.75$ kN·m, $N_D = 30\\times7.5 = 225$ kN → $e = 168.75/225 = 0.75$ m towards the long arm (the column's own weight would shorten it a little).",ar:"**مثال:** إطار T ذراعه الأمامي 4.5 م والخلفي 3 م تحت حمل ميت 30 kN/m: $M_D = 30\\times(4.5^2 - 3^2)/2 = 168.75$ kN·m، و $N_D = 30\\times7.5 = 225$ kN ← $e = 168.75/225 = 0.75$ م ناحية الذراع الطويل (ووزن العمود نفسه هيقصّرها شوية)."}},{t:"p",text:{en:"**Which way to shift.** Always against the base reaction $X$ or the base moment $M$ that the permanent load leaves at the footing:",ar:"**نرحّل في أنهي اتجاه.** دايماً عكس رد الفعل الأفقي $X$ أو العزم $M$ اللي الحمل الدائم بيسيبه عند القاعدة:"}},{t:"steps",items:[{en:"a gable or a frame on two hinges closed by a **tie**: $X = 0$ at the feet — **no shift**;",ar:"جمالون أو إطار على مفصلتين مقفول بـ**شداد**: $X = 0$ عند الرجلين — **مفيش ترحيل**؛"},{en:"a **two-hinged portal**: the footings hold the feet in with $X$, so the frame pushes them out — shift them **outwards**;",ar:"**إطار ذو مفصلين**: القواعد بتمسك الرجلين لجوه بـ $X$، فالإطار بيزقهم لبره — رحّلهم **لبره**؛"},{en:"a **fixed column with a cantilever arm** loaded at its tip: a constant moment down the column — shift **towards the arm**;",ar:"**عمود ثابت بذراع كابولي** محمّل عند طرفه: عزم ثابت نازل في العمود — رحّل **ناحية الذراع**؛"},{en:"the same column with its load close to the knee and a horizontal load at the tip pulling back: the base moment can **reverse** — shift **away from the arm**. Read the sign of the B.M.D at the base before you shift.",ar:"نفس العمود وحمله قريب من الركن وحمل أفقي عند الطرف شادد لورا: عزم القاعدة ممكن **يعكس** — رحّل **بعيد عن الذراع**. اقرا إشارة منحنى العزوم عند القاعدة قبل ما ترحّل."}]},{t:"p",text:{en:"**Example.** A fixed column 6 m high with a 3 m arm: 40 kN at the tip → $M = 40\\times3 = 120$ kN·m at the base, shift towards the arm. The same 40 kN placed 0.5 m from the column, with 15 kN pulling back at the tip: $M = 40\\times0.5 - 15\\times6 = 20 - 90 = -70$ kN·m — the moment has reversed, and the footing is shifted away from the arm.",ar:"**مثال.** عمود ثابت ارتفاعه 6 م بذراع 3 م: 40 kN عند الطرف ← $M = 40\\times3 = 120$ kN·m عند القاعدة، رحّل ناحية الذراع. ونفس الـ 40 kN على بعد 0.5 م من العمود، و 15 kN شادّة لورا عند الطرف: $M = 40\\times0.5 - 15\\times6 = 20 - 90 = -70$ kN·m — العزم عكس، والقاعدة بتترحّل بعيد عن الذراع."}},{t:"quiz",q:{kind:"num",q:{en:"Permanent M = 200 kN·m, N = 320 kN. Footing shift e (m)?",ar:"عزم دائم M = 200 kN·m، و N = 320 kN. ترحيل القاعدة e (م)؟"},answer:.625,tol:.003,unit:"m",explain:{en:"$e = 200/320 = 0.625$ m.",ar:"$e = 200/320 = 0.625$ م."}}}]},{id:"links",title:{en:"Frames with a strut or a tie",ar:"إطارات بدعامة ضغط أو شداد"},blocks:[{t:"p",text:{en:"A link — a strut from the column below the arm, or a tie from a mast above it — props the arm at $k\\,a$ from the column and makes the frame indeterminate to the first degree. Take the link force $X$ as the redundant: $M_1$ is a triangle on the beam part between the column and the link (at the column $k a\\,m/\\ell$, $\\ell$ = the link length) and on the mast or the column part of height $m$; $M_0$ is the plain cantilever.",ar:"الوصلة — دعامة من العمود تحت الذراع، أو شداد من صاري فوقه — بتسند الذراع على بعد $k\\,a$ من العمود وبتخلّي الإطار غير محدد من الدرجة الأولى. خُد قوة الوصلة $X$ هي المجهول الزائد: $M_1$ مثلث على جزء الكمرة اللي بين العمود والوصلة (عند العمود $k a\\,m/\\ell$، و $\\ell$ = طول الوصلة) وعلى الصاري أو جزء العمود اللي ارتفاعه $m$؛ و $M_0$ هو الكابولي العادي."}},{t:"eq",tex:["\\delta_{10} + X\\,\\delta_{11} = 0\\qquad \\delta_{10} + X\\,\\delta_{11} + \\Delta_{tie} = 0","\\Delta_{tie} = \\dfrac{1}{E_c}\\,\\dfrac{L}{n}\\,\\dfrac{F_y}{\\gamma_s}\\ \\ \\ \\ \\Delta_{tie} = \\dfrac{1}{E_c}\\,\\dfrac{L}{n}\\,f_s","M = M_0 + X\\,M_1"],caption:{en:"First line: a strut (or a tie whose extension is neglected); a tie that stretches. Second line: the stretch at ultimate and at working load in its usual form with n = 15 — the same as L·σ/E_s with E_s = 15E_c; with the real E_s = 200 000 N/mm² it is about 1.6 times larger.",ar:"السطر الأول: دعامة ضغط (أو شداد مهملة استطالته)؛ وشداد بيستطيل. السطر التاني: الاستطالة عند الحمل الأقصى وحمل التشغيل بصيغتها المعتادة بـ n = 15 — زي L·σ/E_s بـ E_s = 15E_c؛ وبالـ E_s الحقيقية 200000 N/mm² بتطلع حوالي 1.6 مرة أكبر."}},{t:"p",text:{en:"**Example** (the lab frame): an 8 m arm, $w = 25 + 10 = 35$ kN/m, root depth $8/7.5 = 1.07$ m, the link at $0.7a = 5.6$ m, a 2.5 m mast or strut drop ($\\ell = 6.13$ m). Without a link the root takes $wa^2/2 = 1120$ kN·m. A rigid tie: $X = 312.9$ kN by virtual work (302.1 in the lab), the root drops to about 406 kN·m (430.3). A strut: the column part adds to $\\delta_{10}$, $X = 470.9$ kN (458.8), the root only 45–73 kN·m. **But the base still takes 1120 kN·m** — the pair of link forces is internal to the frame; the footing sees the whole overturning moment. A real RC tie stretches: with just the steel its force needs ($\\sigma = f_y/\\gamma_s$) it would lengthen $6.13\\times347.8/200000 = 10.7$ mm — more than the stiff arm deflects at that point — so it goes slack; with three times that steel it still carries 139.5 kN, with five times 204.7 kN.",ar:"**مثال** (إطار المعمل): ذراع 8 م، و $w = 25 + 10 = 35$ kN/m، وعمق الجذر $8/7.5 = 1.07$ م، والوصلة عند $0.7a = 5.6$ م، وصاري أو نزول دعامة 2.5 م ($\\ell = 6.13$ م). من غير وصلة الجذر بياخد $wa^2/2 = 1120$ kN·m. بشداد جاسئ: $X = 312.9$ kN بالشغل الافتراضي (302.1 في المعمل)، والجذر بينزل لحوالي 406 kN·m (430.3). وبدعامة ضغط: جزء العمود بيضيف على $\\delta_{10}$، و $X = 470.9$ kN (458.8)، والجذر 45–73 kN·m بس. **بس القاعدة لسه بتاخد 1120 kN·m** — زوج قوى الوصلة داخلي في الإطار؛ والقاعدة بتشوف عزم الانقلاب كله. والشداد الخرساني الحقيقي بيستطيل: بالحديد اللي قوته محتاجاه بس ($\\sigma = f_y/\\gamma_s$) كان هيطول $6.13\\times347.8/200000 = 10.7$ مم — أكتر من ترخيم الذراع الجاسئ عند النقطة دي — فبيرتخي؛ وبتلات أضعاف الحديد ده لسه بيشيل 139.5 kN، وبخمس أضعاف 204.7 kN."}},{t:"lab",lab:"frame",height:480,props:{template:"linkframe",lockTemplate:!0,defaultTab:"hand",missions:o},caption:{en:"An 8 m cantilever frame with a tie from a mast, a strut, or no link; the tie rigid or stretching with k times its steel.",ar:"إطار كابولي 8 م بشداد من صاري، أو دعامة ضغط، أو من غير وصلة؛ والشداد جاسئ أو بيستطيل بـ k مرة حديده."}},{t:"quiz",q:{kind:"tf",q:{en:"A strut under the arm of a cantilever frame reduces the moment in its footing.",ar:"دعامة الضغط تحت ذراع الإطار الكابولي بتقلل العزم في قاعدته."},answer:!1,explain:{en:"Only the column below the strut and the footing see the external loads as a whole: their moment is still wa²/2. The strut relieves the arm and the column above it.",ar:"العمود اللي تحت الدعامة والقاعدة بيشوفوا الأحمال الخارجية كلها: عزمهم لسه wa²/2. والدعامة بتريّح الذراع والعمود اللي فوقها."}}}]},{id:"knee",title:{en:"Reinforcing the knee",ar:"تسليح الركن"},blocks:[{t:"steps",items:[{en:"The top (tension) bars of the arm turn down the **outer face of the column** without a break — the knee of a cantilever frame closes.",ar:"الحديد العلوي (الشد) بتاع الذراع بيلف لتحت على **الوش الخارجي للعمود** من غير ما يتقطع — ركن الإطار الكابولي بيقفل."},{en:"**Stirrup hangers** 0.4 A_s on the compression side of the arm — the arm is a frame member, not an ordinary beam with its (0.1–0.2) A_s.",ar:"**كانات تعليق** 0.4 A_s ناحية الضغط في الذراع — الذراع عنصر في إطار، مش كمرة عادية بالـ (0.1–0.2) A_s بتوعها."},{en:"Side bars **2Ø10 every 30 cm** in the deep root.",ar:"أسياخ جانبية **2Ø10 كل 30 سم** في الجذر العميق."},{en:"Ties in the column, and **starter bars** (أشاير) from the footing lapped with the column bars.",ar:"كانات في العمود، و**أشاير** طالعة من القاعدة متراكبة مع حديد العمود."},{en:"On the **compression face of the column** — its stirrup hangers — **0.4 A_s** of the column's tension steel, the same rule as in the arm.",ar:"وعلى **وش الضغط في العمود** — كانات التعليق بتاعته — **0.4 A_s** من حديد الشد بتاع العمود، نفس قاعدة الذراع."}]},{t:"p",text:{en:"**Example:** the 4 m frame above: $M_U = 360$ kN·m on a 300 × 800 root ($d = 750$): $C_1 = 750/\\sqrt{360\\times10^6/(25\\times300)} = 3.42$, $J = 0.777$, $A_s = 1545$ mm² → 4Ø25 on top; hangers $0.4\\times1545 = 618$ mm² → 2Ø20 at the bottom. The RC Frame Studio below designs a frame with an inclined link leg and a cantilever section by section.",ar:"**مثال:** إطار الـ 4 م اللي فوق: $M_U = 360$ kN·m على جذر 300 × 800 ($d = 750$): $C_1 = 750/\\sqrt{360\\times10^6/(25\\times300)} = 3.42$، و $J = 0.777$، و $A_s = 1545$ مم² ← 4Ø25 فوق؛ وكانات تعليق $0.4\\times1545 = 618$ مم² ← 2Ø20 تحت. واستوديو الإطارات الخرسانية اللي تحت بيصمم إطار برجل وصلة مائلة وكابولي قطاع قطاع."}},{t:"lab",lab:"rcframe",height:470,props:{mode:"studio",lockMode:!0,preset:"hall",missions:r},caption:{en:"Switch to the bars and click the numbered sections: the cantilever root, the link, the knees.",ar:"حوّل للحديد واضغط على القطاعات المترقمة: جذر الكابولي والوصلة والأركان."}},{t:"quiz",q:{kind:"num",q:{en:"The arm of a cantilever frame needs A_s = 1800 mm² at its root. Stirrup-hanger area on its compression face by the rule (mm²)?",ar:"ذراع إطار كابولي محتاج A_s = 1800 مم² عند جذره. مساحة كانات التعليق على وش الضغط بالقاعدة (مم²)؟"},answer:720,tol:.003,unit:"mm²",explain:{en:"$0.4\\times1800 = 720$ mm² — a frame member takes 0.4 A_s; an ordinary beam would take only 0.1–0.2 A_s (180–360).",ar:"$0.4\\times1800 = 720$ مم² — عنصر الإطار بياخد 0.4 A_s؛ والكمرة العادية كانت هتاخد 0.1–0.2 A_s بس (180–360)."}}}]},{id:"stands",title:{en:"Grandstands and balance",ar:"المدرجات والاتزان"},blocks:[{t:"p",text:{en:"A grandstand roof cantilevers over the seats from a row of columns at the back. Its permanent moment can be **balanced**: a short back arm carrying a counterweight (a heavy back roof, a wall, the rear stand) until, under the dead load, the column receives almost only a normal force and the footing needs no shift. The live load, snow or wind on the long arm then only swings the moment around zero.",ar:"سقف المدرج بيطلع كابولي فوق الكراسي من صف أعمدة ورا. وعزمه الدائم ممكن يتـ**وازن**: ذراع خلفي قصير شايل ثقل موازنة (سقف خلفي تقيل، أو حائط، أو المدرج اللي ورا) لحد ما العمود تحت الحمل الميت ياخد تقريباً قوة عمودية بس والقاعدة ماتحتاجش ترحيل. وبعدها الحمل الحي أو الرياح على الذراع الطويل بيأرجح العزم حوالين الصفر بس."}},{t:"p",text:{en:"**Example:** a 6 m front arm and a 2 m back arm, dead load 20 kN/m on both: the counterweight $W$ at the back tip that balances the dead load: $20\\times6^2/2 = 20\\times2^2/2 + 2W$ → $W = 160$ kN; then $N = 320$ kN and $M = 0$. Adding a live load of 8 kN/m on the front arm: $M = 8\\times6^2/2 = 144$ kN·m, $N = 368$ kN.",ar:"**مثال:** ذراع أمامي 6 م وخلفي 2 م، وحمل ميت 20 kN/m على الاتنين: ثقل الموازنة $W$ عند طرف الذراع الخلفي اللي بيوازن الحمل الميت: $20\\times6^2/2 = 20\\times2^2/2 + 2W$ ← $W = 160$ kN؛ ويبقى $N = 320$ kN و $M = 0$. ولو زودنا حمل حي 8 kN/m على الذراع الأمامي: $M = 8\\times6^2/2 = 144$ kN·m، و $N = 368$ kN."}},{t:"lab",lab:"frame",height:470,props:{template:"tframe",params:{a:6,a2:2,H:8,g:20,q:8,W:0,load:"front"},lockTemplate:!0,missions:m},caption:{en:"A grandstand roof: remove the live load and find the counterweight that balances the frame.",ar:"سقف مدرج: شيل الحمل الحي ولاقي ثقل الموازنة اللي بيوازن الإطار."}},{t:"quiz",q:{kind:"num",q:{en:"Front arm 5 m, back arm 2 m, dead load 24 kN/m on both. Counterweight at the back tip for zero dead-load moment (kN)?",ar:"ذراع أمامي 5 م وخلفي 2 م، وحمل ميت 24 kN/m على الاتنين. ثقل الموازنة عند طرف الذراع الخلفي لعزم ميت صفر (kN)؟"},answer:126,tol:.003,unit:"kN",explain:{en:"$24\\times25/2 = 24\\times4/2 + 2W$ → $300 = 48 + 2W$ → $W = 126$ kN.",ar:"$24\\times25/2 = 24\\times4/2 + 2W$ ← $300 = 48 + 2W$ ← $W = 126$ kN."}}}]},{id:"slabcol",title:{en:"A cantilever slab hung on a frame column",ar:"بلاطة كابولي متعلّقة على عمود إطار"},blocks:[{t:"p",text:{en:"Up to **2.0 m** an overhang is a **cantilever slab**; beyond 2.0 m it needs a cantilever frame. The slab does not reach the column directly: it hangs on the **edge beam** between the frames, and the edge beam twists. Its **torsion** delivers to each column, at the slab level, a concentrated moment:",ar:"لحد **2.0 م** الكابولي **بلاطة كابولي**؛ وبعد 2.0 م محتاج إطار كابولي. والبلاطة مابتوصلش للعمود على طول: متعلّقة في **الكمرة الطرفية** اللي بين الإطارات، والكمرة الطرفية بتلتوي. و**عزم اللي** بتاعها بيوصّل لكل عمود، عند منسوب البلاطة، عزم مركز:"}},{t:"eq",tex:"M_c = \\dfrac{w_s\\,L_c^2}{2}\\,S",caption:{en:"w_s = ultimate load of the slab per m², L_c = overhang, S = spacing of the frames (the span of the edge beam). The column also receives the vertical load w_s·L_c·S.",ar:"w_s = الحمل الأقصى للبلاطة لكل م²، و L_c = طول الكابولي، و S = المسافة بين الإطارات (بحر الكمرة الطرفية). والعمود بياخد كمان الحمل الرأسي w_s·L_c·S."}},{t:"steps",items:[{en:"In the column of a frame the B.M.D **jumps by $M_c$** at the slab level — a stepped column diagram — and the frame shares out the rest.",ar:"في عمود الإطار منحنى العزوم **بيقفز بـ $M_c$** عند منسوب البلاطة — منحنى عمود متدرّج — والإطار بيوزّع الباقي."},{en:"An outer column fixed at its base whose head is hinged with no horizontal restraint (the end column of a tied saw-tooth, for instance) keeps a **constant $M_c$** from the slab level down to its base.",ar:"والعمود الطرفي الثابت عند قاعدته وراسه مفصلية من غير ما حاجة تمسكها أفقياً (العمود الطرفي لمنشاري بشداد مثلاً) بيفضل عليه **$M_c$ ثابت** من منسوب البلاطة لحد قاعدته."},{en:"The footing is **shifted against $M_c$**, by $e = M_c/N$.",ar:"والقاعدة **بتترحّل عكس $M_c$**، بمسافة $e = M_c/N$."},{en:"**Beyond 2.0 m — a cantilever frame.** A tapered cantilever beam is cast with every frame column at the level of the overhang and carries the slab and, at its tip, the wall. The edge beam then only spans between the frames, with **no torsion**, and the column diagram steps at that level by the root moment of the arm.",ar:"**بعد 2.0 م — إطار كابولي.** كمرة كابولي متدرّجة بتتصب مع كل عمود إطار عند منسوب الكابولي، وشايلة البلاطة وعند طرفها الحائط. والكمرة الطرفية ساعتها بحرها بين الإطارات بس، **من غير عزم لي**، ومنحنى عزوم العمود بيتدرّج عند المنسوب ده بعزم جذر الذراع."}]},{t:"p",text:{en:"**Example.** A two-hinged frame 15 m wide with 6 m columns (400 × 800, beam 400 × 1300), $w = 50$ kN/m, frames every 5 m. A 1.7 m overhang at +4.0 m on the outer face of the left column with $w_s = 12$ kN/m²: $1.7 \\le 2.0$ → a cantilever slab; $M_c = 12\\times1.7^2/2\\times5 = 86.7$ kN·m and $12\\times1.7\\times5 = 102$ kN. In the frame the left column jumps from 265.1 to 351.8 kN·m at +4.0, the left knee rises from 437.2 to 484.4 kN·m and the right one falls to 397.7. On the fixed-base end column of a tied saw-tooth carrying 350 kN, a 1.4 m overhang at +5.0 m with $w_s = 10$ kN/m² and $S = 6$ m gives $M_c = 58.8$ kN·m, constant down to the base: $e = 58.8/(350 + 84) = 0.14$ m.",ar:"**مثال.** إطار ذو مفصلين عرضه 15 م وأعمدته 6 م (400 × 800، والكمرة 400 × 1300)، و $w = 50$ kN/m، والإطارات كل 5 م. كابولي 1.7 م عند +4.0 م على الوش الخارجي للعمود الشمال و $w_s = 12$ kN/m²: $1.7 \\le 2.0$ ← بلاطة كابولي؛ و $M_c = 12\\times1.7^2/2\\times5 = 86.7$ kN·m و $12\\times1.7\\times5 = 102$ kN. وفي الإطار العمود الشمال بيقفز من 265.1 لـ 351.8 kN·m عند +4.0، والركن الشمال بيزيد من 437.2 لـ 484.4 kN·m واليمين بينزل لـ 397.7. وعلى العمود الطرفي الثابت القاعدة لمنشاري بشداد شايل 350 kN، كابولي 1.4 م عند +5.0 م و $w_s = 10$ kN/m² و $S = 6$ م بيدّي $M_c = 58.8$ kN·m، ثابت لحد القاعدة: $e = 58.8/(350 + 84) = 0.14$ م."}},{t:"p",text:{en:"**The edge beam and the bars.** Besides its torsion, the edge beam carries the overhang's vertical load $w_s L_c$ per metre, half of the inner span (the inner span is shared half and half between its two supports, the overhang's effect on that split being ignored) and its own weight — the overhang's part is what reaches each column as $w_s L_c S$. The overhang itself is a solid slab about $L_c/10$ thick. When the roof inside is **ribbed (hollow blocks)**, the top steel of the overhang is given **per rib**: the top bars of every rib run over the edge beam into the solid overhang, and one Ø10 is added **between the ribs** in the solid part. The inner span is designed at mid-span for $wL^2/8 - M_c/2$, a little below its true maximum. **Example** ($f_{cu} = 25$, $f_y = 400$): a 1.8 m overhang 180 mm thick ($1.8/10$), finishes 1.5 and live load 3.0 kN/m²: $w_s = 1.4\\times(0.18\\times25 + 1.5) + 1.6\\times3.0 = 13.2$ kN/m²; with ribs every 0.5 m that is 6.6 kN/m per rib and $M_c = 6.6\\times1.8^2/2 = 10.69$ kN·m per rib. On the solid 500 × 180 strip of one rib ($d = 160$): $C_1 = 5.47$, $J = 0.826$, $A_s = 202$ mm² → 2Ø12 per rib (226), plus one Ø10 between the ribs. A 6.0 m ribbed span with 4.2 kN/m per rib takes $4.2\\times6^2/8 - 10.69/2 = 13.55$ kN·m per rib at mid-span; its true maximum, 2.58 m from its other support, is 13.93 kN·m — 2.8% more.",ar:"**الكمرة الطرفية والحديد.** غير عزم اللي، الكمرة الطرفية شايلة الحمل الرأسي للكابولي $w_s L_c$ لكل متر، ونص البحر اللي جوه (البحر اللي جوه بيتقسم نص ونص على ركيزتيه، وتأثير الكابولي على التقسيمة دي بيتهمل)، ووزنها — وجزء الكابولي هو اللي بيوصل لكل عمود $w_s L_c S$. والكابولي نفسه بلاطة مصمتة تخانتها حوالي $L_c/10$. ولما السقف اللي جوه يبقى **بلاطة هوردي (بأعصاب)**، الحديد العلوي للكابولي بيتحسب **لكل عصب**: الحديد العلوي لكل عصب بيعدّي فوق الكمرة الطرفية لجوه الكابولي المصمت، وبيتزوّد سيخ Ø10 **بين الأعصاب** في الجزء المصمت. والبحر اللي جوه بيتصمم في النص على $wL^2/8 - M_c/2$، أقل شوية من أقصى قيمة حقيقية ليه. **مثال** ($f_{cu} = 25$، و $f_y = 400$): كابولي 1.8 م تخانته 180 مم ($1.8/10$)، وتشطيبات 1.5 وحمل حي 3.0 kN/m²: $w_s = 1.4\\times(0.18\\times25 + 1.5) + 1.6\\times3.0 = 13.2$ kN/m²؛ والأعصاب كل 0.5 م يعني 6.6 kN/m لكل عصب و $M_c = 6.6\\times1.8^2/2 = 10.69$ kN·m لكل عصب. وعلى الشريحة المصمتة 500 × 180 بتاعة عصب واحد ($d = 160$): $C_1 = 5.47$، و $J = 0.826$، و $A_s = 202$ مم² ← 2Ø12 لكل عصب (226)، زائد سيخ Ø10 بين الأعصاب. وبحر هوردي 6.0 م عليه 4.2 kN/m لكل عصب بياخد $4.2\\times6^2/8 - 10.69/2 = 13.55$ kN·m لكل عصب في النص؛ وأقصى قيمة حقيقية ليه، على بعد 2.58 م من ركيزته التانية، 13.93 kN·m — أكتر بـ 2.8%."}},{t:"quiz",q:{kind:"num",q:{en:"A 1.6 m slab overhang, w_s = 12 kN/m², frames every 6 m. Moment M_c on each column (kN·m)?",ar:"كابولي بلاطة 1.6 م، و w_s = 12 kN/m²، والإطارات كل 6 م. العزم M_c على كل عمود (kN·m)؟"},answer:92.16,tol:.003,unit:"kN·m",explain:{en:"$12\\times1.6^2/2\\times6 = 92.16$ kN·m — a slab, since 1.6 ≤ 2.0 m.",ar:"$12\\times1.6^2/2\\times6 = 92.16$ kN·m — بلاطة، لأن 1.6 ≤ 2.0 م."}}}]},{id:"fem",title:{en:"A hall frame with cantilevers: one balance is not enough",ar:"إطار صالة بكوابيل: توازن واحد مش كفاية"},blocks:[{t:"p",text:{en:"A symmetric two-hinged frame without a cantilever is solved with **one balance at the knee**: $M = \\mathrm{F.E.M.}\\times\\mathrm{D.F.}_c$. As soon as a cantilever — a slab or a frame — hangs on its columns, that shortcut **no longer holds**: the joint has a third member, the cantilever's moment $M_c$ must be shared out as well, and a cantilever lower down puts a jump in the column diagram. Solve such a frame with a **full moment-distribution table** — the cantilever is a member with D.F. = 0 that brings $M_c$ to its joint — or by **virtual work**.",ar:"الإطار ذو المفصلين المتماثل من غير كابولي بيتحل بـ**توازن واحد عند الركن**: $M = \\mathrm{F.E.M.}\\times\\mathrm{D.F.}_c$. وأول ما كابولي — بلاطة أو إطار — يتعلّق على أعمدته، الاختصار ده **مابقاش ينفع**: العقدة بقى فيها عضو تالت، وعزم الكابولي $M_c$ لازم يتوزّع هو كمان، والكابولي اللي تحت الركن بيعمل قفزة في منحنى عزوم العمود. حل الإطار ده بـ**جدول توزيع العزوم الكامل** — الكابولي عضو D.F. بتاعه صفر بيجيب $M_c$ لعقدته — أو بـ**الشغل الافتراضي**."}},{t:"eq",tex:["M_1 = \\mathrm{F.E.M.}\\times\\mathrm{D.F.}_c,\\qquad M_F \\approx M_1 + M_c","M_{col} = \\mathrm{D.F.}_c\\,(\\mathrm{F.E.M.} - M_c),\\qquad M_{beam} = M_{col} + M_c = M_1 + \\mathrm{D.F.}_b\\,M_c","M_{beam} = M_1 + M_c - M_c\\,\\dfrac{(h^2 - a^2)/h + L/n}{2h/3 + L/n},\\qquad n = \\dfrac{I_b}{I_c}"],caption:{en:"First line: the quick estimate for a symmetric frame with the same cantilever on both sides — solve it without the cantilever, then add M_c at the knee. Second line: the exact one-row table for a cantilever at the level of the knee (D.F._b + D.F._c = 1). Third line: the exact beam-end moment of a two-hinged frame with prismatic columns of height h when the cantilevers are a above the hinges; a = h gives the second line again.",ar:"السطر الأول: التقدير السريع لإطار متماثل بنفس الكابولي على الناحيتين — حلّه من غير الكابولي، وبعدين زوّد M_c عند الركن. السطر التاني: الجدول المضبوط في صف واحد لكابولي على منسوب الركن (D.F._b + D.F._c = 1). السطر التالت: عزم طرف الكمرة المضبوط لإطار ذو مفصلين أعمدته منتظمة القطاع وارتفاعها h لما الكوابيل تبقى على ارتفاع a فوق المفصلات؛ و a = h بترجّع السطر التاني."}},{t:"p",text:{en:"The estimate keeps the thrust $X$ of the frame without the cantilever: the column keeps its $M_1$ line below the cantilever, the line jumps by $M_c$ at the cantilever, and the beam starts at $M_1 + M_c$. The exact solution shares $M_c$ between the beam and the column, so both take $\\mathrm{D.F.}_c\\,M_c$ **less** than the estimate. $M_1 + M_c$ therefore **overstates the knee** by $\\mathrm{D.F.}_c\\,M_c$ — on the safe side — and **understates the mid-span** moment $wL^2/8 - M_{beam}$ by the same amount — on the unsafe side. Design the span for the exact value.",ar:"التقدير بيحافظ على الدفع $X$ بتاع الإطار من غير الكابولي: العمود بيفضل على خط $M_1$ تحت الكابولي، والخط بيقفز بـ $M_c$ عند الكابولي، والكمرة بتبدأ بـ $M_1 + M_c$. والحل المضبوط بيقسم $M_c$ بين الكمرة والعمود، فالاتنين بياخدوا $\\mathrm{D.F.}_c\\,M_c$ **أقل** من التقدير. يبقى $M_1 + M_c$ **بيكبّر عزم الركن** بـ $\\mathrm{D.F.}_c\\,M_c$ — في ناحية الأمان — و**بيصغّر عزم نص البحر** $wL^2/8 - M_{beam}$ بنفس المقدار — في ناحية الخطر. صمم البحر على القيمة المضبوطة."}},{t:"p",text:{en:"**Example.** A two-hinged frame 18 m wide and 6 m high, beam 400 × 1500, prismatic columns 400 × 1000, $w = 50$ kN/m: $I_b = 0.1125$ and $I_c = 0.0333$ m⁴, $K_c = \\tfrac34\\times0.0333/6 = 0.00417$, $K_b = \\tfrac12\\times0.1125/18 = 0.00313$ → $\\mathrm{D.F.}_c = 0.571$, $\\mathrm{D.F.}_b = 0.429$; $\\mathrm{F.E.M.} = 50\\times18^2/12 = 1350$ kN·m → $M_1 = 771.4$ kN·m. A 3.0 m cantilever frame at each knee carries 25 kN/m and a 15 kN wall at its tip: $M_c = 25\\times3^2/2 + 15\\times3 = 157.5$ kN·m. **Estimate:** knee $771.4 + 157.5 = 928.9$, mid-span $2025 - 928.9 = 1096.1$ kN·m. **Table:** column $0.571\\times(1350 - 157.5) = 681.4$, beam $681.4 + 157.5 = 838.9$, mid-span $2025 - 838.9 = 1186.1$ kN·m. The estimate is $0.571\\times157.5 = 90.0$ kN·m too high at the knee and too low in the span (7.6%). With the same cantilever 4.0 m above the hinges instead of at the knee, the exact knee is 782.7 and the mid-span 1242.3 kN·m, while the estimate still says 928.9 and 1096.1 — the lower the cantilever, the worse the shortcut. By the third line: $n = 0.1125/0.0333 = 3.375$, $L/n = 5.333$, $M_{beam} = 928.93 - 157.5\\times(20/6 + 5.333)/(4 + 5.333) = 928.93 - 146.25 = 782.68$ kN·m.",ar:"**مثال.** إطار ذو مفصلين عرضه 18 م وارتفاعه 6 م، والكمرة 400 × 1500، والأعمدة منتظمة 400 × 1000، و $w = 50$ kN/m: $I_b = 0.1125$ و $I_c = 0.0333$ م⁴، و $K_c = \\tfrac34\\times0.0333/6 = 0.00417$، و $K_b = \\tfrac12\\times0.1125/18 = 0.00313$ ← $\\mathrm{D.F.}_c = 0.571$ و $\\mathrm{D.F.}_b = 0.429$؛ و $\\mathrm{F.E.M.} = 50\\times18^2/12 = 1350$ kN·m ← $M_1 = 771.4$ kN·m. إطار كابولي 3.0 م عند كل ركن شايل 25 kN/m وحائط 15 kN عند طرفه: $M_c = 25\\times3^2/2 + 15\\times3 = 157.5$ kN·m. **التقدير:** الركن $771.4 + 157.5 = 928.9$، ونص البحر $2025 - 928.9 = 1096.1$ kN·m. **الجدول:** العمود $0.571\\times(1350 - 157.5) = 681.4$، والكمرة $681.4 + 157.5 = 838.9$، ونص البحر $2025 - 838.9 = 1186.1$ kN·m. التقدير أعلى بـ $0.571\\times157.5 = 90.0$ kN·m عند الركن وأقل بنفس القيمة في البحر (7.6%). ولو نفس الكابولي على ارتفاع 4.0 م فوق المفصلات بدل الركن، الركن المضبوط 782.7 ونص البحر 1242.3 kN·m، والتقدير لسه بيقول 928.9 و 1096.1 — وكل ما الكابولي ينزل، الاختصار يبوظ أكتر. وبالسطر التالت: $n = 0.1125/0.0333 = 3.375$، و $L/n = 5.333$، و $M_{beam} = 928.93 - 157.5\\times(20/6 + 5.333)/(4 + 5.333) = 928.93 - 146.25 = 782.68$ kN·m."}},{t:"quiz",q:{kind:"num",q:{en:"Symmetric two-hinged frame: D.F._c = 0.6, F.E.M. = 1000 kN·m, a cantilever at each knee with M_c = 150 kN·m. Exact moment at the top of the column (kN·m)?",ar:"إطار ذو مفصلين متماثل: D.F._c = 0.6، و F.E.M. = 1000 kN·m، وكابولي عند كل ركن M_c = 150 kN·m. العزم المضبوط عند راس العمود (kN·m)؟"},answer:510,tol:.003,unit:"kN·m",explain:{en:"$0.6\\times(1000 - 150) = 510$ kN·m; the beam end takes $510 + 150 = 660$ — the estimate $M_1 + M_c = 600 + 150 = 750$ is $0.6\\times150 = 90$ too high.",ar:"$0.6\\times(1000 - 150) = 510$ kN·m؛ وطرف الكمرة بياخد $510 + 150 = 660$ — والتقدير $M_1 + M_c = 600 + 150 = 750$ أعلى بـ $0.6\\times150 = 90$."}}}]},{id:"carried",title:{en:"Cantilever frames that carry — or ride on — another system",ar:"إطارات كابولي شايلة نظام تاني — أو راكبة عليه"},blocks:[{t:"steps",items:[{en:"**Fixed, never hinged.** A cantilever frame standing on another system must be fixed to it; on a hinge it is unstable.",ar:"**مثبت، مش مفصلي أبداً.** الإطار الكابولي الواقف على نظام تاني لازم يبقى مثبت فيه؛ على مفصلة بيبقى غير مستقر."},{en:"**A system on the tips.** A saw-tooth girder (or a bridge) spanning between the tips of two cantilever frames sits on **real supports**: with a tie, a hinge and a roller; without a tie, two hinges, so that its thrust does not sway it. Each tip then receives $Y_1$ down and, without a tie, $X\\cdot S$ pushing it back towards its own column. The column takes $Y_1 L_c$ (plus the arm's own load) at its top and $Y_1 L_c - X\\,S\\,H$ at its base: the diagram may change sign along the column, and the footing is shifted against the **base** moment. Depth: $L_c/(2 \\to 3)$.",ar:"**نظام على الأطراف.** كمرة منشارية (أو كوبري) بحرها بين طرفين إطارين كابولي بتركب على **ركائز حقيقية**: بشداد، مفصلة وركيزة متحركة؛ ومن غير شداد، مفصلتين، علشان دفعها مايعملهاش إزاحة جانبية. وكل طرف بياخد $Y_1$ لتحت، ومن غير شداد $X\\cdot S$ بتزقه لورا ناحية عموده. والعمود بياخد $Y_1 L_c$ (زائد حمل الذراع نفسه) عند راسه و $Y_1 L_c - X\\,S\\,H$ عند قاعدته: المنحنى ممكن يغيّر إشارته على طول العمود، والقاعدة بتترحّل عكس عزم **القاعدة**. والعمق: $L_c/(2 \\to 3)$."},{en:"**Two storeys of frames.** For stacked two-hinged frames, solve the **carried** (upper) frame first, then put its reactions **reversed** on the knees of the lower one — $Y$ down and $X$ outwards — together with the lower frame's own load.",ar:"**إطارات على دورين.** في الإطارات ذات المفصلين اللي فوق بعض، حل الإطار **المحمول** (اللي فوق) الأول، وبعدين حط ردود أفعاله **معكوسة** على أركان اللي تحته — $Y$ لتحت و $X$ لبره — مع الحمل بتاع الإطار اللي تحت نفسه."},{en:"**Cantilever frames fixed on a two-hinged frame** (an upper saw-tooth without a tie): their moments follow from statics, and the lower frame takes half the total load at each hinge. For a quick $X$, assume **M = 0 at L/5** from each knee on its beam and take moments of the left part about that point. At the knee the beam moment is the algebraic sum of the two column moments.",ar:"**إطارات كابولي مثبتة على إطار ذو مفصلين** (منشاري فوق من غير شداد): عزومها بتطلع من الاتزان، والإطار اللي تحت بياخد نص الحمل الكلي عند كل مفصلة. ولـ $X$ سريعة، افرض **M = 0 عند L/5** من كل ركن على كمرته وخد عزوم الجزء الشمال حوالين النقطة دي. وعند الركن عزم الكمرة هو المجموع الجبري لعزمي العمودين."},{en:"**Bars.** The top bars of the arm turn down the outer face of the upper column, run through the lower knee and are anchored $L_d$ into the lower column; the inner bars of the upper column also run $L_d$ past the lower beam.",ar:"**الحديد.** الحديد العلوي بتاع الذراع بيلف لتحت على الوش الخارجي للعمود اللي فوق، ويعدّي الركن اللي تحت، ويتثبت $L_d$ جوه العمود اللي تحت؛ والحديد الداخلي للعمود اللي فوق برضه بيعدّي $L_d$ بعد الكمرة اللي تحت."}]},{t:"p",text:{en:"**Example 1.** A 3.5 m arm carries a saw-tooth girder reaction $Y_1 = 180$ kN at its tip and 20 kN/m of its own; the column is 7 m high: $M_{top} = 180\\times3.5 + 20\\times3.5^2/2 = 752.5$ kN·m. With a tie the base keeps 752.5 kN·m. Without a tie, $X\\cdot S = 30$ kN at the tip: $752.5 - 30\\times7 = 542.5$ kN·m at the base; with $X\\cdot S = 150$ kN: $752.5 - 1050 = -297.5$ kN·m — the moment changes sign along the column and the footing is shifted the other way.",ar:"**مثال 1.** ذراع 3.5 م شايل رد فعل كمرة منشارية $Y_1 = 180$ kN عند طرفه و 20 kN/m من وزنه؛ والعمود ارتفاعه 7 م: $M_{top} = 180\\times3.5 + 20\\times3.5^2/2 = 752.5$ kN·m. بشداد القاعدة بيفضل عليها 752.5 kN·m. ومن غير شداد، $X\\cdot S = 30$ kN عند الطرف: $752.5 - 30\\times7 = 542.5$ kN·m عند القاعدة؛ ولو $X\\cdot S = 150$ kN: $752.5 - 1050 = -297.5$ kN·m — العزم بيغيّر إشارته على طول العمود والقاعدة بتترحّل في الاتجاه التاني."}},{t:"p",text:{en:"**Example 2.** A two-hinged frame 15 m wide and 5 m high (columns and beam 400 × 1000), $w = 25$ kN/m, carries on each knee a cantilever frame: a 3 m column and a 2.5 m arm over the hall with 50 kN at the tip and 8 kN/m. Each upper column hands its knee $50 + 8\\times2.5 = 70$ kN and $50\\times2.5 + 8\\times2.5^2/2 = 150$ kN·m; at each hinge $Y = (25\\times15 + 2\\times70)/2 = 257.5$ kN. With $M = 0$ at $15/5 = 3.0$ m: $257.5\\times3.0 - 5X - 50\\times0.5 - 20\\times1.75 - 75\\times1.5 = 0$ → $X = 120.0$ kN; the lower column takes $120\\times5 = 600$ kN·m and the beam at the knee $600 - 150 = 450$ kN·m. The exact analysis of this frame gives $X = 101.2$ kN, 506.2 and 356.2 kN·m: the estimate treats the knees as almost fixed, so it is on the safe side at the knees — the span needs the exact moments (346.9 kN·m at mid-span).",ar:"**مثال 2.** إطار ذو مفصلين عرضه 15 م وارتفاعه 5 م (الأعمدة والكمرة 400 × 1000)، و $w = 25$ kN/m، شايل على كل ركن إطار كابولي: عمود 3 م وذراع 2.5 م فوق الصالة عليه 50 kN عند الطرف و 8 kN/m. كل عمود فوق بيسلّم ركنه $50 + 8\\times2.5 = 70$ kN و $50\\times2.5 + 8\\times2.5^2/2 = 150$ kN·m؛ وعند كل مفصلة $Y = (25\\times15 + 2\\times70)/2 = 257.5$ kN. وبـ $M = 0$ عند $15/5 = 3.0$ م: $257.5\\times3.0 - 5X - 50\\times0.5 - 20\\times1.75 - 75\\times1.5 = 0$ ← $X = 120.0$ kN؛ والعمود اللي تحت بياخد $120\\times5 = 600$ kN·m والكمرة عند الركن $600 - 150 = 450$ kN·m. والتحليل المضبوط للإطار ده بيدّي $X = 101.2$ kN، و 506.2 و 356.2 kN·m: التقريب بيعامل الأركان كأنها تقريباً ثابتة، فهو في ناحية الأمان عند الأركان — والبحر محتاج العزوم المضبوطة (346.9 kN·m في النص)."}},{t:"quiz",q:{kind:"num",q:{en:"A cantilever frame with a 4.0 m arm carries a saw-tooth girder at its tip. Root and column depth by L_c/2.5 (m)?",ar:"إطار كابولي ذراعه 4.0 م شايل كمرة منشارية عند طرفه. عمق الجذر والعمود بـ L_c/2.5 (م)؟"},answer:1.6,tol:.003,unit:"m",explain:{en:"$4.0/2.5 = 1.6$ m, inside $L_c/2 \\to L_c/3 = 2.0 \\to 1.33$ m — far deeper than the $L_c/5 = 0.8$ m of a uniformly loaded arm.",ar:"$4.0/2.5 = 1.6$ م، جوه $L_c/2 \\to L_c/3 = 2.0 \\to 1.33$ م — أعمق بكتير من $L_c/5 = 0.8$ م بتاعة الذراع المحمّل بحمل موزع."}}}]},{id:"pulled",title:{en:"A cantilever frame pulled at its tip — and a strut",ar:"إطار كابولي متشدود من طرفه — ودعامة ضغط"},blocks:[{t:"p",text:{en:"The tip of a cantilever frame is not always pushed back towards its column. Let the arm carry the **low hinge of a sloping slab** whose upper edge rests on a **post leaning outwards** — the post's foot under the slab, on a second column. The post pushes the top of the slab away from the hinge, so the slab **pulls the tip towards the post** with $X\\cdot S$: the arm is in **tension** and the base moment **adds** instead of subtracting.",ar:"طرف الإطار الكابولي مش دايماً بيتزق لورا ناحية عموده. خلّي الذراع شايل **المفصلة الواطية لبلاطة مائلة** حرفها العلوي راكب على **قائم مايل لبره** — رجل القائم تحت البلاطة، على عمود تاني. القائم بيزق أعلى البلاطة بعيد عن المفصلة، فالبلاطة **بتشد الطرف ناحية القائم** بـ $X\\cdot S$: الذراع في **شد**، وعزم القاعدة **بيتجمع** بدل ما يتطرح."}},{t:"eq",tex:["M_B = V\\,L_c + \\dfrac{w_a\\,L_c^2}{2},\\qquad M_A = M_B + X\\,S\\,H","e_s = e - \\dfrac{t}{2} + c,\\qquad A_s = \\dfrac{M_s}{J\\,f_y\\,d} + \\dfrac{T}{f_y/\\gamma_s}","e_s = e + \\dfrac{t}{2} - c,\\qquad A_s = \\dfrac{M_s}{J\\,f_y\\,d} - \\dfrac{P}{f_y/\\gamma_s}","d_{min} = C_{1,min}\\sqrt{\\dfrac{M_s}{f_{cu}\\,b}}"],caption:{en:"First line: A = the base of the cantilever column, B = the root of the arm, C = its tip; V = the vertical load at C, w_a = the arm's own load, H = the height of the column AB. Second line: the arm in tension T = X·S with a large eccentricity (e = M/T, e/t > 0.5), M_s = T·e_s. Third line: the column base in compression with e/t > 0.5, M_s = P·e_s. Last line: the smallest depth that keeps a section under-reinforced (C₁,min = 2.78 for f_y = 360).",ar:"السطر الأول: A = قاعدة العمود الكابولي، و B = جذر الذراع، و C = طرفه؛ و V = الحمل الرأسي عند C، و w_a = حمل الذراع نفسه، و H = ارتفاع العمود AB. السطر التاني: الذراع في شد T = X·S بلامركزية كبيرة (e = M/T، و e/t > 0.5)، و M_s = T·e_s. السطر التالت: قاعدة العمود في ضغط و e/t > 0.5، و M_s = P·e_s. السطر الأخير: أقل عمق بيخلّي القطاع ناقص التسليح (C₁,min = 2.78 لـ f_y = 360)."}},{t:"steps",items:[{en:"**Over-reinforced column base.** If $C_1 < C_{1,min}$, either add compression steel from the interaction diagram or **deepen the section** to $d_{min}$ and design it again with the new $t$ ($e_s$ and the check $P/(f_{cu}\\,b\\,t) < 0.04$ change). Deepening is usually preferred: the diagram asks for heavy steel on both faces.",ar:"**قاعدة عمود زائدة التسليح.** لو $C_1 < C_{1,min}$، يا إما تضيف حديد ضغط من منحنى التفاعل يا إما **تعمّق القطاع** لـ $d_{min}$ وتصممه تاني بالـ $t$ الجديدة (الـ $e_s$ وشرط $P/(f_{cu}\\,b\\,t) < 0.04$ بيتغيّروا). والتعميق غالباً هو الأحسن: منحنى التفاعل بيطلب حديد تقيل على الوشين."},{en:"**Compression face of the column**: about **0.4 A_s**.",ar:"**وش الضغط في العمود**: حوالي **0.4 A_s**."},{en:"**The post column.** The second column carries the post: its head receives the vertical load and the horizontal push of the post, about $X\\cdot S$ back towards the arm — a cantilever column with $M = H_{post}\\,h$ at its base.",ar:"**عمود القائم.** العمود التاني شايل القائم: راسه بتاخد الحمل الرأسي والزقة الأفقية للقائم، حوالي $X\\cdot S$ راجعة ناحية الذراع — عمود كابولي عزمه عند قاعدته $M = H_{post}\\,h$."},{en:"**A strut closes the loop.** Join the tip C of the arm to the head E of the post column with a strut **CE**: it carries $X\\cdot S$ in **compression**, the pull and the push cancel inside the frame, the cantilever column keeps the **constant** $M_B$ down to its base, and the post column carries axial load only. Shift the cantilever footing by $e = M_B/N$; the post footing stays centric. The strut is an axial member, buckling neglected: $P_u = 0.35\\,A_c\\,f_{cu} + 0.67\\,A_s\\,f_y$, with $A_s \\ge 0.8\\%\\,A_c$.",ar:"**دعامة ضغط بتقفل الدايرة.** اربط طرف الذراع C براس عمود القائم E بدعامة ضغط **CE**: بتشيل $X\\cdot S$ **ضغط**، والشدة والزقة بيلغوا بعض جوه الإطار، والعمود الكابولي بيفضل عليه $M_B$ **ثابت** لحد قاعدته، وعمود القائم بيشيل حمل محوري بس. رحّل قاعدة العمود الكابولي $e = M_B/N$؛ وقاعدة عمود القائم بتفضل في النص. والدعامة عضو محوري، والانبعاج مهمل: $P_u = 0.35\\,A_c\\,f_{cu} + 0.67\\,A_s\\,f_y$، و $A_s \\ge 0.8\\%\\,A_c$."}]},{t:"p",text:{en:"**Example** ($f_{cu} = 25$, $f_y = 360$, frames every 5 m). A 2.5 m arm 400 × 900 ($d = 850$) with 14 kN/m of its own carries at its tip $V = 260$ kN and $X\\cdot S = 90$ kN towards the post; the column is 6.5 m high with $N = 420$ kN at its base. $M_B = 260\\times2.5 + 14\\times2.5^2/2 = 693.75$ kN·m and $M_A = 693.75 + 90\\times6.5 = 1278.75$ kN·m. **Arm** ($T = 90$ kN): $e = 7.71$ m, $e/t = 8.6$, $e_s = 7.71 - 0.45 + 0.05 = 7.31$ m, $M_s = 657.8$ kN·m; $C_1 = 3.31$, $J = 0.769$: $A_s = 2794 + 287.5 = 3081$ mm² → 7Ø25 in one row. **Column base** 400 × 1000: $P/(f_{cu}\\,b\\,t) = 0.042 > 0.04$; $e = 3.045$ m, $e_s = 3.045 + 0.50 - 0.05 = 3.495$ m, $M_s = 1467.8$ kN·m; $C_1 = 950/383.1 = 2.48 < 2.78$ — over-reinforced. Deepen: $d_{min} = 2.78\\times383.1 = 1065$ → $d = 1100$, $t = 1200$ mm; now $P/(f_{cu}\\,b\\,t) = 0.035 < 0.04$ and P is neglected: $C_1 = 3.08$, $J = 0.750$, $A_s = 4304$ mm² → 9Ø25, with $0.4A_s = 1721$ mm² (4Ø25) on the compression face. **Post column** without a strut: $M = 90\\times6.5 = 585$ kN·m at its base. **With a 300 × 300 strut**: 90 kN of compression, against $0.35\\times90\\,000\\times25 = 787.5$ kN for the concrete alone, so the minimum $0.8\\%\\times90\\,000 = 720$ mm² governs → 4Ø16 (804); the cantilever column keeps 693.75 kN·m down to its base, its footing shifted $e = 693.75/420 = 1.65$ m; the post column carries axial load only.",ar:"**مثال** ($f_{cu} = 25$، و $f_y = 360$، والإطارات كل 5 م). ذراع 2.5 م مقاس 400 × 900 ($d = 850$) ووزنه 14 kN/m، شايل عند طرفه $V = 260$ kN و $X\\cdot S = 90$ kN ناحية القائم؛ والعمود ارتفاعه 6.5 م و $N = 420$ kN عند قاعدته. $M_B = 260\\times2.5 + 14\\times2.5^2/2 = 693.75$ kN·m و $M_A = 693.75 + 90\\times6.5 = 1278.75$ kN·m. **الذراع** ($T = 90$ kN): $e = 7.71$ م، و $e/t = 8.6$، و $e_s = 7.71 - 0.45 + 0.05 = 7.31$ م، و $M_s = 657.8$ kN·m؛ و $C_1 = 3.31$، و $J = 0.769$: $A_s = 2794 + 287.5 = 3081$ مم² ← 7Ø25 في صف واحد. **قاعدة العمود** 400 × 1000: $P/(f_{cu}\\,b\\,t) = 0.042 > 0.04$؛ و $e = 3.045$ م، و $e_s = 3.045 + 0.50 - 0.05 = 3.495$ م، و $M_s = 1467.8$ kN·m؛ و $C_1 = 950/383.1 = 2.48 < 2.78$ — زائد التسليح. عمّق: $d_{min} = 2.78\\times383.1 = 1065$ ← $d = 1100$ و $t = 1200$ مم؛ ودلوقتي $P/(f_{cu}\\,b\\,t) = 0.035 < 0.04$ والـ P بتتهمل: $C_1 = 3.08$، و $J = 0.750$، و $A_s = 4304$ مم² ← 9Ø25، و $0.4A_s = 1721$ مم² (4Ø25) على وش الضغط. **عمود القائم** من غير دعامة: $M = 90\\times6.5 = 585$ kN·m عند قاعدته. **وبدعامة 300 × 300**: ضغط 90 kN، قصاد $0.35\\times90\\,000\\times25 = 787.5$ kN للخرسانة لوحدها، فالحد الأدنى $0.8\\%\\times90\\,000 = 720$ مم² هو اللي بيحكم ← 4Ø16 (804)؛ والعمود الكابولي بيفضل عليه 693.75 kN·m لحد قاعدته، وقاعدته مترحّلة $e = 693.75/420 = 1.65$ م؛ وعمود القائم بيشيل حمل محوري بس."}},{t:"quiz",q:{kind:"num",q:{en:"The tip of a cantilever frame is pulled towards a post by X·S = 160.5 kN; the root moment is M_B = 507.8 kN·m and the column 7.5 m high. Moment at the base (kN·m)?",ar:"طرف إطار كابولي متشدود ناحية قائم بـ X·S = 160.5 kN؛ وعزم الجذر M_B = 507.8 kN·m والعمود ارتفاعه 7.5 م. العزم عند القاعدة (kN·m)؟"},answer:1711.55,tol:.003,unit:"kN·m",explain:{en:"$507.8 + 160.5\\times7.5 = 507.8 + 1203.75 = 1711.6$ kN·m — the pull adds to the root moment. A strut to the post column would leave the constant 507.8 kN·m instead.",ar:"$507.8 + 160.5\\times7.5 = 507.8 + 1203.75 = 1711.6$ kN·m — الشدة بتتجمع على عزم الجذر. ودعامة ضغط لعمود القائم كانت هتسيب 507.8 kN·m ثابتة بدل كده."}}}]},{id:"apply",title:{en:"Your building: a terrace and a canopy on cantilever frames",ar:"مبناك: تراس ومظلة على إطارات كابولي"},blocks:[{t:"p",text:{en:"The balcony of your building is a 1.5 m cantilever slab — within the 2 m a slab covers. Deepen it into a **4.5 m covered terrace** and it becomes a cantilever-frame span (2–6 m): beams at the columns A1–A3, $S = 5$ m apart, $t = 4.5/5 = 0.90$ m at the root, $b = \\max(0.30,\\ 5/20) = 0.30$ m, 0.45 m at the tip. A 150 mm slab with 1.5 kN/m² finishes and 3 kN/m² live load: $w_s = 1.4\\times5.25 + 1.6\\times3 = 12.15$ kN/m²; one interior beam carries $12.15\\times5 + 5.51 = 66.26$ kN/m → $M = 66.26\\times4.5^2/2 = 670.9$ kN·m and $N = 298.2$ kN. The column would have to be 720–900 mm deep — the building's columns are 500. A strut from column A2, 1.5 m below the floor, to $0.7L_c$ takes 553.2 kN and leaves 78.2 kN·m at the root; but column A2 below the strut and its footing still carry 670.9 kN·m — the footing shifted $e = 670.9/866.4 = 0.77$ m.",ar:"بلكونة مبناك بلاطة كابولي 1.5 م — جوه الـ 2 م اللي البلاطة بتغطيها. عمّقها لـ**تراس مسقوف 4.5 م** يبقى في مدى الإطار الكابولي (2–6 م): كمرات عند الأعمدة A1–A3، بينها $S = 5$ م، و $t = 4.5/5 = 0.90$ م عند الجذر، و $b = \\max(0.30,\\ 5/20) = 0.30$ م، و 0.45 م عند الطرف. بلاطة 150 مم بتشطيبات 1.5 kN/m² وحمل حي 3 kN/m²: $w_s = 1.4\\times5.25 + 1.6\\times3 = 12.15$ kN/m²؛ والكمرة الوسطية شايلة $12.15\\times5 + 5.51 = 66.26$ kN/m ← $M = 66.26\\times4.5^2/2 = 670.9$ kN·m و $N = 298.2$ kN. العمود كان لازم يبقى عمقه 720–900 مم — وأعمدة المبنى 500. ودعامة ضغط من العمود A2 تحت الأرضية بـ 1.5 م لحد $0.7L_c$ بتاخد 553.2 kN وبتسيب 78.2 kN·m عند الجذر؛ بس العمود A2 اللي تحت الدعامة وقاعدته لسه شايلين 670.9 kN·m — والقاعدة مترحّلة $e = 670.9/866.4 = 0.77$ م."}},{t:"p",text:{en:"The entrance canopy (4 m wide, 1.6 m deep) could stand on a single post as a **balanced T-frame** with two 2 m arms instead of the arch: $w_T = 13.55$ and $w_D = 10.99$ kN/m. Live load on both arms: $M = 0$, $N = 54.2$ kN; on one arm only: $M = (13.55 - 10.99)\\times2^2/2 = 5.12$ kN·m — against 36.0 kN·m at the foot of each arch post under its 25.7 kN thrust. Click the balcony.",ar:"ومظلة المدخل (عرضها 4 م وعمقها 1.6 م) ممكن تقف على عمود واحد كـ**إطار T متزن** بذراعين 2 م بدل العقد: $w_T = 13.55$ و $w_D = 10.99$ kN/m. الحمل الحي على الذراعين: $M = 0$ و $N = 54.2$ kN؛ وعلى ذراع واحد بس: $M = (13.55 - 10.99)\\times2^2/2 = 5.12$ kN·m — قصاد 36.0 kN·m عند رجل كل عمود من عمودين العقد تحت دفعه 25.7 kN. اضغط على البلكونة."}},{t:"widget",w:"building",props:{focus:"BAL",tags:["footings","cols-g","beams-1","slab-1","balcony","canopy","sys-cantilever"]}},{t:"quiz",q:{kind:"num",q:{en:"The 4.5 m terrace beam with w = 66.26 kN/m: root moment (kN·m)?",ar:"كمرة التراس 4.5 م و w = 66.26 kN/m: عزم الجذر (kN·m)؟"},answer:670.9,tol:.003,unit:"kN·m",explain:{en:"$66.26\\times4.5^2/2 = 670.9$ kN·m.",ar:"$66.26\\times4.5^2/2 = 670.9$ kN·m."}}}]}],quiz:[{kind:"num",q:{en:"A 5.5 m cantilever frame. Root depth (m)?",ar:"إطار كابولي 5.5 م. عمق الجذر (م)؟"},answer:1.1,tol:.003,unit:"m",explain:{en:"$L_c/5 = 1.1$ m.",ar:"$L_c/5 = 1.1$ م."}},{kind:"num",q:{en:"Cantilever frames 8 m apart. Width b (m)?",ar:"إطارات كابولي بينها 8 م. العرض b (م)؟"},answer:.4,tol:.003,unit:"m",explain:{en:"$\\max(0.30,\\ 8/20 = 0.40) = 0.40$ m.",ar:"$\\max(0.30,\\ 8/20 = 0.40) = 0.40$ م."}},{kind:"num",q:{en:"Single cantilever frame, arm 3.5 m, w = 40 kN/m. Base moment (kN·m)?",ar:"إطار كابولي، الذراع 3.5 م، و w = 40 kN/m. عزم القاعدة (kN·m)؟"},answer:245,tol:.003,unit:"kN·m",explain:{en:"$40\\times3.5^2/2 = 245$ kN·m.",ar:"$40\\times3.5^2/2 = 245$ kN·m."}},{kind:"mcq",q:{en:"A T-frame with equal arms gets its largest normal force when…",ar:"إطار T بذراعين متساويين بياخد أكبر قوة عمودية لما…"},options:[{en:"both arms carry the total load",ar:"الذراعين شايلين الحمل الكلي"},{en:"one arm carries the total load",ar:"ذراع واحد شايل الحمل الكلي"},{en:"only the dead load acts",ar:"الحمل الميت بس مؤثر"}],answer:0,explain:{en:"N is the sum of both arms' loads; the moment is then zero.",ar:"N مجموع أحمال الذراعين؛ والعزم ساعتها صفر."}},{kind:"num",q:{en:"Link frame: EI·δ₁₀ = −9000, EI·δ₁₁ = 30 (same EI units). Link force X (kN)?",ar:"إطار بوصلة: EI·δ₁₀ = −9000، و EI·δ₁₁ = 30 (نفس وحدات EI). قوة الوصلة X (kN)؟"},answer:300,tol:.003,unit:"kN",explain:{en:"$X = 9000/30 = 300$ kN.",ar:"$X = 9000/30 = 300$ kN."}},{kind:"tf",q:{en:"A tie designed exactly for its force stretches by L·(f_y/γ_s)/E_s, whatever the force.",ar:"الشداد المصمم على قوته بالظبط بيستطيل L·(f_y/γ_s)/E_s، أياً كانت القوة."},answer:!0,explain:{en:"Its stress is always f_y/γ_s, so its strain — and its elongation — are fixed.",ar:"إجهاده دايماً f_y/γ_s، فانفعاله — واستطالته — ثابتين."}},{kind:"num",q:{en:"Permanent M = 450 kN·m on a cantilever frame with Y = 600 kN. Footing shift (m)?",ar:"عزم دائم M = 450 kN·m على إطار كابولي و Y = 600 kN. ترحيل القاعدة (م)؟"},answer:.75,tol:.003,unit:"m",explain:{en:"$e = 450/600 = 0.75$ m, inside the usual 0.5–1.0 m.",ar:"$e = 450/600 = 0.75$ م، جوه المدى المعتاد 0.5–1.0 م."}},{kind:"mcq",q:{en:"The side bars in the deep root of a cantilever frame are…",ar:"الأسياخ الجانبية في الجذر العميق للإطار الكابولي…"},options:[{en:"2Ø10 every 30 cm",ar:"2Ø10 كل 30 سم"},{en:"5Ø16 per metre",ar:"5Ø16 في المتر"},{en:"not needed",ar:"مش مطلوبة"}],answer:0,explain:{en:"They hold the deep web against shrinkage and support the stirrups.",ar:"بتمسك العصب العميق ضد الانكماش وبتشيل الكانات."}}]};export{$ as default};
